+  return typeof value === 'object' && value !== null;
+}
+
+function validateSessionCursor(value: unknown):
+  | {valid: true; cursor: {updatedAt: string | number; sessionId: string}}
+  | {valid: false; error: string} {
+  if (!isRecord(value)) return {valid: false, error: 'list_sessions before must be an object'};
+  if (typeof value.sessionId !== 'string' || value.sessionId.length < 1 || value.sessionId.length > 128) {
+    return {valid: false, error: 'list_sessions before.sessionId must be 1-128 characters'};
+  }
+  if (!isValidSessionDate(value.updatedAt)) {
+    return {valid: false, error: 'list_sessions before.updatedAt must be a valid date'};
+  }
+  return {valid: true, cursor: {updatedAt: value.updatedAt, sessionId: value.sessionId}};
+}
+
+function isValidSessionDate(value: unknown): value is string | number {
+  if (typeof value === 'string') return !Number.isNaN(Date.parse(value));
+  return typeof value === 'number' && Number.isFinite(value) && !Number.isNaN(new Date(value).getTime());
+}
+
+function isValidConversationSessionId(value: unknown): value is string {
+  return typeof value === 'string' && value.length >= 1 && value.length <= 128;
+}
+
+const messageValidators: Record<string, MessageValidator> = {
+  user_message: validateUserMessage,
+  ping: validatePingMessage,
+  list_sessions: validateListSessionsMessage,
+  list_conversations: validateListConversationsMessage,
+};

}
```

| Field       | Type   | Required | Description                      |
| ----------- | ------ | -------- | -------------------------------- |
| `type`      | string | Yes      | `"ping"`                         |
| `timestamp` | number | Yes      | Client timestamp in milliseconds |

### 4.3 list_sessions

Requests the conversation summaries belonging to the authenticated user. The server takes the user id from the connection, never from the frame, and forwards the optional pagination fields to the session store.

```json
{
  "type": "list_sessions",
  "limit": 10,
  "before": {
    "updatedAt": "2026-01-01T00:05:00.000Z",
    "sessionId": "s3"
  }
}
```

| Field    | Type    | Required | Description                                   |
| -------- | ------- | -------- | --------------------------------------------- |
| `type`   | string  | Yes      | `"list_sessions"`                             |
| `limit`  | integer | No       | Non-negative page size                        |
| `before` | object  | No       | Cursor containing `updatedAt` and `sessionId` |

Unknown fields, including `userId`, are ignored. A malformed `limit` or cursor is answered with `INVALID_MESSAGE` without calling the store ([validated by: accepts a bare list_sessions frame and rejects a malformed limit or before with INVALID_MESSAGE without calling listFor](../../src/transport/conversationList.acceptance.test.ts#L150)).

The request is answered independently of the per-session turn lock, so a list can be returned while a `user_message` is streaming ([validated by: answers a ping at once while a run is pending](../../src/transport/ws/messageHandler.test.ts#L726)).

## 5. Server-to-Client Messages

### 5.1 connected
- `stream_end` follows every stream even after an error: a failed run sends its `error` frame first and `stream_end` last.
- An `error` frame does not by itself end a stream. It is advisory: it may concern the run in flight or an unrelated frame, such as a malformed `ping`.
- The client SHOULD use this message to clear any "processing" or "loading" indicators.
- The client MUST treat a run as complete only at `stream_end` or when the socket closes. Unparseable JSON is the one frame answered with `INVALID_FORMAT` and no `stream_end`, because the server cannot tell what it was meant to be; for it the client falls back on the socket closing.

### 5.9 session_list

Carries the summaries requested by `list_sessions`. The response contains metadata only: no conversation entries or credentials are sent. Dates are ISO-8601 strings because these are JSON protocol values ([validated by: answers list_sessions for the authenticated user with ISO dates, forwarding limit and before while ignoring any client userId](../../src/transport/conversationList.acceptance.test.ts#L80)).

```json
{
  "type": "session_list",
  "sessions": [
    {
      "sessionId": "s3",
      "createdAt": "2026-01-01T00:00:00.000Z",
      "updatedAt": "2026-01-01T00:02:00.000Z",
      "entryCount": 4
    }
  ]
}
```

| Field      | Type   | Required | Description                          |
| ---------- | ------ | -------- | ------------------------------------ |
| `type`     | string | Yes      | `"session_list"`                     |
| `sessions` | array  | Yes      | Summaries for the authenticated user |

The server sends an empty `sessions` array when the configured store has no `listFor`; a store failure instead produces the existing `SERVER_ERROR` frame and a `ws` log ([validated by: answers an empty session_list when the store has no listFor, and SERVER_ERROR with a ws error log when listFor throws](../../src/transport/conversationList.acceptance.test.ts#L121)).

## 6. SessionEntry Objects

A SessionEntry represents a single piece of content in the conversation. Every entry has a `role` field that determines its shape. The `role` acts as a discriminant for the union type.

